// amplify_outputs.json is generated by `npx amplify sandbox` / Amplify
// deployment and is gitignored - it won't exist in a fresh checkout or in
// CI. import.meta.glob (unlike a static import) doesn't fail the build when
// the file is missing: it just resolves to an empty object, so the app can
// build and run without it.
const modules = import.meta.glob('../amplify_outputs.json', { eager: true })
const match = Object.values(modules)[0]

export const amplifyOutputs = match?.default ?? null
